-- ================================================================
-- SHESAFE | BANCO FINAL | PostgreSQL puro (SEM PostGIS)
-- Dados reais fornecidos/obtidos para o projeto. Não cria risco fictício.
-- Coordenadas: latitude/longitude simples. Saúde: centroides derivados
-- matematicamente das geometrias oficiais apenas quando necessário para mapa.
-- Rotas: estrutura para cálculo/integração; NÃO são rotas fictícias pré-cadastradas.
-- ================================================================

CREATE EXTENSION IF NOT EXISTS pgcrypto;
DROP SCHEMA IF EXISTS shesafe CASCADE;
CREATE SCHEMA shesafe;
SET search_path TO shesafe, public;

CREATE TABLE fonte_dados (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 nome text NOT NULL UNIQUE,
 orgao text NOT NULL,
 url text,
 tipo text NOT NULL DEFAULT 'OFICIAL' CHECK (tipo IN ('OFICIAL','DADO_ABERTO','FORNECIDO_PELO_PROJETO','DERIVADO')),
 descricao text,
 data_atualizacao timestamptz,
 ativo boolean NOT NULL DEFAULT true,
 criado_em timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE territorio (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 nome text NOT NULL,
 tipo text NOT NULL CHECK (tipo IN ('MUNICIPIO','RPA','MICRORREGIAO','BAIRRO','LOGRADOURO')),
 codigo_externo text,
 rpa_codigo integer,
 microregiao_codigo integer,
 ativo boolean NOT NULL DEFAULT true,
 criado_em timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX territorio_tipo_idx ON territorio(tipo);
CREATE INDEX territorio_nome_idx ON territorio(nome);
CREATE UNIQUE INDEX territorio_codigo_tipo_uq ON territorio(tipo,codigo_externo) WHERE codigo_externo IS NOT NULL;

CREATE TABLE usuario_app (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 nome text NOT NULL,
 email text NOT NULL UNIQUE,
 senha_hash text NOT NULL,
 telefone text,
 ativo boolean NOT NULL DEFAULT true,
 criado_em timestamptz NOT NULL DEFAULT now(),
 atualizado_em timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE papel (id smallserial PRIMARY KEY, nome text NOT NULL UNIQUE);
CREATE TABLE usuario_papel (usuario_id uuid NOT NULL REFERENCES usuario_app(id) ON DELETE CASCADE, papel_id smallint NOT NULL REFERENCES papel(id) ON DELETE CASCADE, PRIMARY KEY(usuario_id,papel_id));


CREATE TABLE indicador_violencia (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 territorio_id uuid REFERENCES territorio(id),
 nome_territorio text NOT NULL,
 periodo text NOT NULL,
 violencia_domestica integer CHECK (violencia_domestica IS NULL OR violencia_domestica >= 0),
 estupro integer CHECK (estupro IS NULL OR estupro >= 0),
 feminicidio integer CHECK (feminicidio IS NULL OR feminicidio >= 0),
 fonte_id uuid NOT NULL REFERENCES fonte_dados(id),
 observacao text,
 criado_em timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX indicador_violencia_territorio_idx ON indicador_violencia(nome_territorio);

CREATE TABLE ponto_apoio (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 nome text NOT NULL,
 tipo text NOT NULL CHECK (tipo IN ('DEAM','DELEGACIA','CENTRO_REFERENCIA_MULHER','CREAS','CRAS','DEFENSORIA_PUBLICA','MINISTERIO_PUBLICO','SAUDE','OUTRO')),
 subtipo text,
 endereco text,
 bairro text,
 telefone text,
 atendimento text,
 latitude double precision,
 longitude double precision,
 geometria_original jsonb,
 fonte_id uuid REFERENCES fonte_dados(id),
 confirmado boolean NOT NULL DEFAULT false,
 observacao text,
 ativo boolean NOT NULL DEFAULT true,
 criado_em timestamptz NOT NULL DEFAULT now(),
 CHECK ((latitude IS NULL AND longitude IS NULL) OR (latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180))
);
CREATE INDEX ponto_apoio_tipo_idx ON ponto_apoio(tipo);
CREATE INDEX ponto_apoio_coords_idx ON ponto_apoio(latitude,longitude);

CREATE TABLE infraestrutura (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 nome text NOT NULL,
 tipo text NOT NULL DEFAULT 'WIFI_PUBLICO' CHECK (tipo = 'WIFI_PUBLICO'),
 bairro text,
 rpa text,
 regiao text,
 endereco text,
 latitude double precision NOT NULL,
 longitude double precision NOT NULL,
 fonte_id uuid REFERENCES fonte_dados(id),
 data_referencia timestamptz,
 ativo boolean NOT NULL DEFAULT true,
 CHECK (latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180)
);
CREATE INDEX infraestrutura_coords_idx ON infraestrutura(latitude,longitude);
CREATE INDEX infraestrutura_bairro_idx ON infraestrutura(bairro);

CREATE TABLE unidade_saude (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 nome text NOT NULL,
 tipo text,
 endereco text,
 patrimonio text,
 latitude double precision,
 longitude double precision,
 geometria_oficial jsonb NOT NULL,
 fonte_id uuid REFERENCES fonte_dados(id),
 observacao text DEFAULT 'Latitude/longitude, quando preenchidas, são centroides derivados da geometria oficial; não substituem o endereço oficial.',
 ativo boolean NOT NULL DEFAULT true
);
CREATE INDEX unidade_saude_tipo_idx ON unidade_saude(tipo);

CREATE TABLE canal_emergencia (
 id serial PRIMARY KEY,
 nome text NOT NULL UNIQUE,
 numero text,
 descricao text,
 observacao text,
 ativo boolean NOT NULL DEFAULT true
);


CREATE TABLE rota (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 usuario_id uuid REFERENCES usuario_app(id) ON DELETE SET NULL,
 origem_descricao text,
 destino_descricao text,
 origem_latitude double precision NOT NULL,
 origem_longitude double precision NOT NULL,
 destino_latitude double precision NOT NULL,
 destino_longitude double precision NOT NULL,
 modo text NOT NULL DEFAULT 'A_PE' CHECK (modo IN ('A_PE','BICICLETA','CARRO')),
 provedor text,
 id_rota_provedor text,
 distancia_metros numeric(12,2),
 duracao_minutos integer,
 status text NOT NULL DEFAULT 'SOLICITADA' CHECK (status IN ('SOLICITADA','CALCULADA','EXPIRADA','INDISPONIVEL')),
 criado_em timestamptz NOT NULL DEFAULT now(),
 calculado_em timestamptz,
 CHECK (origem_latitude BETWEEN -90 AND 90 AND destino_latitude BETWEEN -90 AND 90),
 CHECK (origem_longitude BETWEEN -180 AND 180 AND destino_longitude BETWEEN -180 AND 180)
);
CREATE INDEX rota_usuario_idx ON rota(usuario_id);

CREATE TABLE rota_recurso (
 id bigserial PRIMARY KEY,
 rota_id uuid NOT NULL REFERENCES rota(id) ON DELETE CASCADE,
 ponto_apoio_id uuid REFERENCES ponto_apoio(id) ON DELETE CASCADE,
 infraestrutura_id uuid REFERENCES infraestrutura(id) ON DELETE CASCADE,
 distancia_origem_metros numeric(12,2),
 papel text NOT NULL CHECK (papel IN ('APOIO','POLICIA','SAUDE','WIFI')),
 criado_em timestamptz NOT NULL DEFAULT now(),
 CHECK ((ponto_apoio_id IS NOT NULL AND infraestrutura_id IS NULL) OR (ponto_apoio_id IS NULL AND infraestrutura_id IS NOT NULL))
);

CREATE TABLE situacao_risco (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 territorio_id uuid REFERENCES territorio(id),
 nivel text NOT NULL CHECK (nivel IN ('VERMELHO','AMARELO','VERDE','CINZA')),
 periodo text,
 metodologia text NOT NULL,
 evidencias text,
 fonte_id uuid REFERENCES fonte_dados(id),
 publicado boolean NOT NULL DEFAULT false,
 observacao text NOT NULL DEFAULT 'Classificação estatística/aproximada. Ausência de registros não significa ausência de risco. Não representa garantia de segurança.'
);

CREATE TABLE log_auditoria (
 id bigserial PRIMARY KEY,
 usuario_id uuid REFERENCES usuario_app(id) ON DELETE SET NULL,
 tabela text NOT NULL,
 operacao text NOT NULL CHECK (operacao IN ('INSERT','UPDATE','DELETE','IMPORT','VALIDACAO','PUBLICACAO')),
 registro_id text,
 descricao text,
 criado_em timestamptz NOT NULL DEFAULT now()
);

CREATE OR REPLACE FUNCTION distancia_metros(lat1 double precision, lon1 double precision, lat2 double precision, lon2 double precision)
RETURNS double precision LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE r constant double precision := 6371000; dlat double precision; dlon double precision; a double precision;
BEGIN
 IF NULL IN (lat1,lon1,lat2,lon2) THEN RETURN NULL; END IF;
 dlat := radians(lat2-lat1); dlon := radians(lon2-lon1);
 a := sin(dlat/2)^2 + cos(radians(lat1))*cos(radians(lat2))*sin(dlon/2)^2;
 RETURN 2*r*atan2(sqrt(a),sqrt(1-a));
END $$;

CREATE OR REPLACE FUNCTION pontos_apoio_proximos(p_lat double precision,p_lon double precision,p_raio_metros double precision DEFAULT 3000)
RETURNS TABLE(id uuid,nome text,tipo text,endereco text,telefone text,latitude double precision,longitude double precision,distancia_metros double precision)
LANGUAGE sql STABLE AS $$
 SELECT p.id,p.nome,p.tipo,p.endereco,p.telefone,p.latitude,p.longitude,
        distancia_metros(p_lat,p_lon,p.latitude,p.longitude)
 FROM ponto_apoio p
 WHERE p.ativo=true AND p.latitude IS NOT NULL AND p.longitude IS NOT NULL
   AND distancia_metros(p_lat,p_lon,p.latitude,p.longitude) <= GREATEST(p_raio_metros,0)
 ORDER BY distancia_metros(p_lat,p_lon,p.latitude,p.longitude);
$$;

CREATE OR REPLACE FUNCTION wifi_proximo(p_lat double precision,p_lon double precision,p_raio_metros double precision DEFAULT 1000)
RETURNS TABLE(id uuid,nome text,endereco text,bairro text,latitude double precision,longitude double precision,distancia_metros double precision)
LANGUAGE sql STABLE AS $$
 SELECT i.id,i.nome,i.endereco,i.bairro,i.latitude,i.longitude,
        distancia_metros(p_lat,p_lon,i.latitude,i.longitude)
 FROM infraestrutura i
 WHERE i.ativo=true
   AND distancia_metros(p_lat,p_lon,i.latitude,i.longitude) <= GREATEST(p_raio_metros,0)
 ORDER BY distancia_metros(p_lat,p_lon,i.latitude,i.longitude);
$$;







