CREATE OR REPLACE VIEW vw_pontos_apoio AS SELECT id,nome,tipo,subtipo,endereco,bairro,telefone,atendimento,latitude,longitude,confirmado,observacao FROM ponto_apoio WHERE ativo=true;
CREATE OR REPLACE VIEW vw_wifi AS SELECT id,nome,bairro,rpa,regiao,endereco,latitude,longitude FROM infraestrutura WHERE ativo=true;
CREATE OR REPLACE VIEW vw_indicadores AS SELECT i.*,f.nome AS fonte FROM indicador_violencia i JOIN fonte_dados f ON f.id=i.fonte_id;
CREATE OR REPLACE VIEW vw_resumo_banco AS SELECT (SELECT count(*) FROM infraestrutura) AS total_wifi, (SELECT count(*) FROM unidade_saude) AS total_unidades_saude, (SELECT count(*) FROM ponto_apoio) AS total_pontos_apoio, (SELECT count(*) FROM indicador_violencia) AS total_indicadores, (SELECT count(*) FROM territorio WHERE tipo='BAIRRO') AS total_bairros, (SELECT count(*) FROM territorio WHERE tipo='LOGRADOURO') AS total_logradouros;
CREATE OR REPLACE FUNCTION atualizar_data_usuario() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.atualizado_em=now(); RETURN NEW; END $$;
CREATE TRIGGER trg_usuario_atualizado BEFORE UPDATE ON usuario_app FOR EACH ROW EXECUTE FUNCTION atualizar_data_usuario();

-- Segurança: os dados estatísticos são agregados e não armazenam endereço de vítima.
-- Rotas não recebem trajetos inventados. O backend deverá consultar um provedor de rotas
-- quando houver origem/destino e gravar distancia/duracao/provedor na tabela rota.

COMMIT;

